 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The grid is split by solid horizontal and vertical lines of one color.
    div = next(v for v in range(10)
               if any(all(x == v for x in row) for row in grid)
               and any(all(grid[r][c] == v for r in range(h)) for c in range(w)))
    rb, cb = [], []
    start = 0
    for r in range(h):
        if all(x == div for x in grid[r]):
            if r > start:
                rb.append((start, r))
            start = r + 1
    if start < h:
        rb.append((start, h))
    start = 0
    for c in range(w):
        if all(grid[r][c] == div for r in range(h)):
            if c > start:
                cb.append((start, c))
            start = c + 1
    if start < w:
        cb.append((start, w))
    counts = Counter(x for row in grid for x in row if x != div)
    background = counts.most_common(1)[0][0]
    return [[1 if sum(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1)) == 2 else background
             for c0, c1 in cb] for r0, r1 in rb]
